import{_ as t,o,c as d,ag as a}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"HTTP API Reference","description":"Every HTTP route MuxitServer exposes, with the auth rule for each.","frontmatter":{"title":"HTTP API Reference","description":"Every HTTP route MuxitServer exposes, with the auth rule for each."},"headers":[],"relativePath":"reference/http-api.md","filePath":"reference/http-api.md"}'),r={name:"reference/http-api.md"};function c(s,e,n,i,h,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="http-api-reference" tabindex="-1">HTTP API Reference <a class="header-anchor" href="#http-api-reference" aria-label="Permalink to &quot;HTTP API Reference&quot;">​</a></h1><p>The WebSocket carries the live protocol; these HTTP routes cover what a plain request does better — sign-in, file reads and writes, the first-run picker, diagnostics from another machine. The <a href="./websocket-api.html">WebSocket API</a> page documents the messages; this page documents the routes.</p><p>All routes live under <code>/api/</code> on the same origin as the UI (<code>http://127.0.0.1:8765</code> by default). Bodies are JSON unless a route says otherwise; error bodies are <code>{ error, code? }</code>.</p><h2 id="auth-rules" tabindex="-1">Auth rules <a class="header-anchor" href="#auth-rules" aria-label="Permalink to &quot;Auth rules&quot;">​</a></h2><p>Four rules apply, in this order, after one check that every request passes first. Each route below names the ones that matter for it.</p><p><strong>Host check.</strong> Every request — every path, WebSocket upgrades and static files included — must name this server in its <code>Host</code> header, or it is refused with 403 <code>{ error, code: &quot;HOST_NOT_ALLOWED&quot;, hint }</code> before any rule below is consulted. Allowed: <code>localhost</code>, <code>*.localhost</code>, <code>127.0.0.1</code>, <code>[::1]</code>, the IP address the connection arrived on, the names in <code>security.hostnames</code>, and — with remote access on — this machine&#39;s host name, <code>&lt;host&gt;.local</code> and the mDNS name. The port is not compared. This is what stops DNS rebinding: a rebound page is same-origin with itself, so the same-origin rule below cannot tell it apart, but its <code>Host</code> is the attacker&#39;s name. Clients that use <code>127.0.0.1</code> or <code>localhost</code> are unaffected; see <a href="/guides/remote-access.html#host-names">Host names</a> for tunnels and proxies.</p><table tabindex="0"><thead><tr><th>Rule</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Same-origin writes</strong></td><td>Every POST, PUT and DELETE under <code>/api/</code> and <code>/mcp</code> that carries a browser <code>Origin</code> or <code>Sec-Fetch-Site</code> header must be same-origin, or it is refused with 403 <code>CROSS_ORIGIN_BLOCKED</code>. Non-browser clients send neither header and are unaffected.</td></tr><tr><td><strong>Token</strong></td><td>With <code>security.remoteAccess</code> on, a non-loopback request needs the remote-access token — password or not; with no password set there is nothing to log in with, so the request gets 401 <code>REMOTE_PASSWORD_NOT_SET</code> unless it holds the startup token: <code>X-Auth-Token: &lt;token&gt;</code> (or <code>?token=</code> for <code>&lt;img&gt;</code>-style loads). The token is the <code>sessionToken</code> from <code>POST /api/auth/login</code>, or the startup token read from <code>workspace/config/.auth-token</code> by something with access to the machine. Loopback requests never need it. <code>/api/auth/login</code>, <code>/api/auth/status</code>, <code>/api/auth/token</code> and <code>/api/eula/*</code> are exempt so a client can get in before it has one.</td></tr><tr><td><strong>Loopback only</strong></td><td>Answers only from the machine itself, whatever token is presented.</td></tr><tr><td><strong>Write gate</strong></td><td>The <a href="/guides/operator-mode.html">operator-mode</a> verdict, read from the <code>X-Muxit-Account</code> header: an admin or engineer passes, a signed-in operator or an anonymous caller on a locked station (or under the <code>login</code> visitor policy) gets 403 with <code>OPERATOR_MODE_RESTRICTED</code> or <code>OPERATOR_SIGN_IN_REQUIRED</code>. Reads are never gated.</td></tr></tbody></table><p>An account-session token (from <a href="#accounts"><code>/api/accounts/login</code></a>) is a second credential on top of the transport token — it says <em>who</em> is acting, and travels only as <code>X-Muxit-Account</code> on HTTP or the <code>account-&lt;token&gt;</code> subprotocol on the socket, never in the query string.</p><h2 id="remote-access" tabindex="-1">Remote access <a class="header-anchor" href="#remote-access" aria-label="Permalink to &quot;Remote access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/auth/token</code></td><td>Loopback only, same-origin browser fetch</td><td><code>{ token }</code> — the startup token, for the UI&#39;s own bootstrap. 403 <code>{ requiresLogin: true }</code> from any other host; non-browser clients read <code>workspace/config/.auth-token</code> instead</td></tr><tr><td><code>GET /api/auth/status</code></td><td>None</td><td><code>{ remoteAccess, isLocal, requiresLogin, hasPassword, httpsEnabled, sessionValid, localAddresses }</code>. <code>requiresLogin</code> is true for every non-loopback caller while remote access is on, even before a password is set (the login page then reports that none is). <code>sessionValid</code> is set when the request presents a token, so a UI can detect a stale one after a restart</td></tr><tr><td><code>POST /api/auth/login</code></td><td>None</td><td><code>{ password }</code> → <code>{ sessionToken }</code> — the only credential a remote client is given; use it as <code>X-Auth-Token</code> and as the WebSocket <code>auth-&lt;token&gt;</code> subprotocol. It ends on logout, on a password change and after 24 hours, and a WebSocket opened with it is then closed with code <code>4401</code>. 401 <code>{ error, retryAfter }</code> on a wrong password, 429 <code>{ error, retryAfter }</code> when rate-limited (5 per minute per IP), 503 <code>{ error, code: &quot;REMOTE_PASSWORD_NOT_SET&quot; }</code> when no password is configured</td></tr><tr><td><code>POST /api/auth/logout</code></td><td>Token</td><td>Ends the presented session token. <code>{ status: &quot;logged_out&quot; }</code></td></tr><tr><td><code>POST /api/auth/password</code></td><td>Loopback, or Token</td><td><code>{ password }</code> sets the remote-access password (8+ characters, upper, lower, digit). Ends every remote session</td></tr><tr><td><code>DELETE /api/auth/password</code></td><td>Loopback only</td><td>Removes the password. Ends every remote session</td></tr></tbody></table><h2 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h2><p><a href="/guides/accounts.html">User accounts</a> — admin, engineer and operator sign-in with a PIN. The account feature is Pro and up; while the tier blocks it, writes here return 403 with <code>blockedReason</code> and the store is not loaded.</p><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/accounts</code></td><td>Token</td><td><code>{ available, blockedReason, graceUntil, graceReason, graceCause, configured, hasAdmin, canBootstrap, anonymous, idleTimeoutMinutes, accounts: [{ id, name, role }], roles, pinMinimum: { admin, engineer, operator } }</code>. Names and roles only, never hashes; readable by anyone who can reach the server, because the sign-in screen needs the list</td></tr><tr><td><code>GET /api/accounts/session</code></td><td>Token + <code>X-Muxit-Account</code></td><td>Who the presented account token belongs to: <code>{ id, name, role }</code>, or 401. Lets a reloaded tab restore its session</td></tr><tr><td><code>POST /api/accounts/login</code></td><td>Token</td><td><code>{ id, pin }</code> → <code>{ token, id, name, role }</code>. One undifferentiated 401 <code>{ error, retryAfter }</code> for an unknown id, a wrong PIN or a lockout (per IP and per account, 30 s doubling to 15 min after five failures)</td></tr><tr><td><code>POST /api/accounts/logout</code></td><td>Token</td><td>Ends the presented account token. <code>{ ok: true }</code></td></tr><tr><td><code>POST /api/accounts</code></td><td>Admin</td><td><code>{ id, name, role, pin? }</code> creates or updates an account; an absent <code>pin</code> keeps the current one, a new one ends that account&#39;s sessions. → <code>{ ok, accounts, hasAdmin }</code>. The first account must be an admin</td></tr><tr><td><code>POST /api/accounts/delete</code></td><td>Admin</td><td><code>{ id }</code> → <code>{ ok, accounts }</code>. Ends the account&#39;s sessions</td></tr><tr><td><code>POST /api/accounts/policy</code></td><td>Admin</td><td><code>{ anonymous?, idleTimeoutMinutes? }</code> — <code>anonymous</code> is <code>full</code>, <code>dashboard</code> or <code>login</code>; <code>dashboard</code> needs a license covering operator mode (400 <code>OPERATOR_MODE_RESTRICTED</code> otherwise). → <code>{ ok, anonymous, idleTimeoutMinutes }</code></td></tr></tbody></table><p><strong>Admin</strong> means a caller whose <code>X-Muxit-Account</code> resolves to an admin. Before any admin exists, the three management routes accept a loopback caller or one holding the transport token, so the first admin can be created; a signed-in operator or engineer never qualifies on their own.</p><h2 id="operator-mode" tabindex="-1">Operator mode <a class="header-anchor" href="#operator-mode" aria-label="Permalink to &quot;Operator mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/operator</code></td><td>Token</td><td>Station status for the shell: <code>{ enabled, licenseBlocked, graceUntil, graceReason, graceCause, chatEnabled, chatDashboards, hasContent, dashboards, landing, scripts, scriptCount, folder, accountsConfigured, anonymous, hasAuthor, accounts }</code>. <code>enabled</code> is the effective state (policy asks for a locked station <em>and</em> the license allows it); operator content is whatever sits under <code>scripts/operator/</code> and <code>dashboards/operator/</code></td></tr></tbody></table><h2 id="dashboards-assets-and-labels" tabindex="-1">Dashboards, assets and labels <a class="header-anchor" href="#dashboards-assets-and-labels" aria-label="Permalink to &quot;Dashboards, assets and labels&quot;">​</a></h2><p>Always registered, editor mode or not — production panels run with editor mode off and still need their dashboards, logos and label templates.</p><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/dashboards</code></td><td>Token</td><td><code>[{ name, path }]</code>, recursive under <code>workspace/dashboards/</code>, forward-slash relative names</td></tr><tr><td><code>GET /api/dashboards/{name}</code></td><td>Token</td><td>The dashboard JSON as text. 400 on a bad name, 404 when missing</td></tr><tr><td><code>PUT /api/dashboards/{name}</code></td><td>Token, write gate</td><td>Body is the dashboard JSON (must parse). → <code>{ name, path }</code>. 400 on invalid JSON, 404 when the target folder does not exist</td></tr><tr><td><code>GET /api/assets/{path}</code></td><td>Token (<code>?token=</code> allowed)</td><td>A file from <code>workspace/assets/</code> with its media type. Images, <code>mp4</code>/<code>webm</code>, <code>mp3</code>/<code>wav</code>/<code>ogg</code> and <code>pdf</code> only; <code>..</code> and anything outside the folder are refused</td></tr><tr><td><code>GET /api/labels</code></td><td>Token</td><td><code>[{ name, path }]</code> — the label templates</td></tr><tr><td><code>GET /api/labels/{name}</code></td><td>Token</td><td>Raw template JSON. 400 / 404 as for dashboards</td></tr><tr><td><code>PUT /api/labels/{name}</code></td><td>Token, write gate</td><td>Validate and save. 200 <code>{ name, path, warnings }</code>, 400 <code>{ error, errors }</code></td></tr><tr><td><code>DELETE /api/labels/{name}</code></td><td>Token, write gate</td><td>204, or 404 <code>{ error }</code></td></tr></tbody></table><h2 id="connectors-and-scripts" tabindex="-1">Connectors and scripts <a class="header-anchor" href="#connectors-and-scripts" aria-label="Permalink to &quot;Connectors and scripts&quot;">​</a></h2><p>Creation only — content is edited through the editor routes, and scripts run by name over the WebSocket.</p><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>POST /api/connectors</code></td><td>Token, write gate</td><td><code>{ baseName, content }</code> writes a new <code>workspace/connectors/&lt;baseName&gt;.js</code>, suffixing the name if it exists. → <code>{ name, fileName, path }</code></td></tr><tr><td><code>HEAD /api/connectors/{name}</code></td><td>Token</td><td>200 when <code>connectors/&lt;name&gt;.js</code> exists, 404 otherwise</td></tr><tr><td><code>GET /api/scripts</code></td><td>Token</td><td><code>[{ name, fileName, path, running }]</code> for <code>workspace/scripts/*.js</code></td></tr><tr><td><code>POST /api/scripts</code></td><td>Token, write gate</td><td>Body is the script text; creates <code>scripts/new-script.js</code> (or <code>new-script-N.js</code>). → <code>{ name, fileName, path }</code></td></tr><tr><td><code>GET /api/startup-scripts</code></td><td>Token</td><td>Same shape for <code>workspace/startup/*.js</code>; startup scripts run at boot on Maker and up</td></tr><tr><td><code>POST /api/startup-scripts</code></td><td>Token, write gate</td><td>As <code>POST /api/scripts</code>, into <code>startup/</code></td></tr></tbody></table><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h2><p>Registered only when <code>security.editorMode</code> is true. Every route needs the <strong>startup token</strong> exactly — an account-session token is not enough — and is refused for a gated caller. Paths are workspace-relative; <code>config/</code> is never readable and <code>config/</code> and <code>drivers/</code> are never writable (403 <code>PATH_FORBIDDEN</code>).</p><table tabindex="0"><thead><tr><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/editor/files?path=</code></td><td>Directory listing: <code>[{ name, path, type: &quot;directory&quot; | &quot;file&quot;, size? }]</code>. Empty path is the workspace root; <code>config/</code> is hidden</td></tr><tr><td><code>GET /api/editor/files/{path}</code></td><td>File content as text</td></tr><tr><td><code>HEAD /api/editor/files/{path}</code></td><td>200 / 404</td></tr><tr><td><code>PUT /api/editor/files/{path}</code></td><td>Body is the new content; creates parent folders</td></tr><tr><td><code>DELETE /api/editor/files/{path}</code></td><td>200 / 404</td></tr><tr><td><code>POST /api/editor/rename</code></td><td><code>{ oldPath, newPath }</code> — rename or move</td></tr><tr><td><code>POST /api/editor/mkdir</code></td><td><code>{ path }</code></td></tr><tr><td><code>GET /api/editor/raw/{path}</code></td><td>The file with a proper media type (images, video, …) for previews</td></tr><tr><td><code>POST /api/editor/reveal</code></td><td><code>{ path }</code> — show the file in the OS file manager</td></tr><tr><td><code>POST /api/editor/open-with</code></td><td><code>{ path }</code> — open with the system default app. Executable and scriptable extensions are refused with 403 <code>{ error, extension }</code></td></tr></tbody></table><h2 id="workspaces-and-the-picker" tabindex="-1">Workspaces and the picker <a class="header-anchor" href="#workspaces-and-the-picker" aria-label="Permalink to &quot;Workspaces and the picker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/workspaces</code></td><td>Token</td><td>The catalog: <code>[{ path, name, lastOpened, exists }]</code>, most recent first. Entries whose folder was deleted are dropped from the catalog first; <code>exists: false</code> is left only for a folder whose parent is missing too (a drive or share that is not connected)</td></tr><tr><td><code>GET /api/workspaces/current</code></td><td>Token</td><td><code>{ path, name }</code> of the open workspace</td></tr><tr><td><code>GET /api/boot-mode</code></td><td>Token</td><td><code>{ mode: &quot;picker&quot; | &quot;ready&quot; }</code> — whether the server is still waiting for a workspace to be chosen</td></tr><tr><td><code>GET /api/picker/slot-status</code></td><td>Token</td><td><code>{ atCap, tier?, limit?, taken?, upgradeUrl? }</code> — the concurrent-instance cap, for the picker&#39;s banner</td></tr><tr><td><code>POST /api/workspaces</code></td><td>Token, write gate</td><td><code>{ path, name }</code> creates a workspace in a new or empty directory. → <code>{ path, name, created: true }</code></td></tr><tr><td><code>POST /api/workspaces/open</code></td><td>Token, write gate</td><td><code>{ path }</code> adds an existing workspace to the catalog. → <code>{ path, name }</code></td></tr><tr><td><code>POST /api/workspaces/switch</code></td><td>Token, write gate</td><td><code>{ path }</code> restarts into that workspace. 403 with the cap details when the tier&#39;s instance limit is reached</td></tr><tr><td><code>POST /api/workspaces/rename</code></td><td>Token, write gate</td><td><code>{ path, name }</code> renames the catalog entry</td></tr><tr><td><code>POST /api/workspaces/remove</code></td><td>Token, write gate</td><td><code>{ path }</code> removes it from the catalog; no files are deleted</td></tr><tr><td><code>GET /api/workspaces/browse?path=</code></td><td>Token</td><td>Directory list for the folder picker</td></tr><tr><td><code>POST /api/workspaces/browse/mkdir</code></td><td>Token, write gate</td><td><code>{ path }</code> creates a directory for the picker</td></tr></tbody></table><h2 id="workspace-eula" tabindex="-1">Workspace EULA <a class="header-anchor" href="#workspace-eula" aria-label="Permalink to &quot;Workspace EULA&quot;">​</a></h2><p>Reachable before anything else, because a workspace stays in Sandbox mode (reads work, hardware writes and <code>scripts.start</code> fail with <code>EULA_NOT_ACCEPTED</code>) until the EULA is accepted.</p><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/eula</code></td><td>None</td><td><code>{ currentVersion, isAccepted, reason, acceptedVersion, acceptedAt, acceptedBy, acceptedLicenseId, acceptedInstanceId, writeLockReason, canonicalText, canonicalHash }</code>. <code>reason</code> is <code>EulaMissing</code>, <code>EulaCorrupt</code> or <code>EulaOutdated</code></td></tr><tr><td><code>GET /api/eula/text?version=</code></td><td>None</td><td>The canonical text as <code>text/markdown</code>; 404 <code>EULA_UNKNOWN_VERSION</code> for a version the server does not ship</td></tr><tr><td><code>POST /api/eula/accept</code></td><td>Same-origin</td><td><code>{ userIdentifier }</code> → <code>{ isAccepted, acceptedVersion, acceptedAt, acceptedBy, acceptedLicenseId, acceptedInstanceId }</code>. Unlocks the workspace</td></tr><tr><td><code>GET /api/eula/history</code></td><td>None</td><td>The append-only acceptance history, newest first</td></tr></tbody></table><h2 id="diagnostics-and-logs" tabindex="-1">Diagnostics and logs <a class="header-anchor" href="#diagnostics-and-logs" aria-label="Permalink to &quot;Diagnostics and logs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/diagnostics/network</code></td><td>Token</td><td><code>{ bind, os, interfaces, firewall, mdns, hints, verbose, fixCommands? }</code>. Full report from loopback; a redacted one (no interface IPs, firewall rules or fix commands) for anyone else, so a leaked token cannot map the host</td></tr><tr><td><code>GET /api/logs</code></td><td>Loopback only</td><td>The server log ring buffer: <code>[{ level, source, message, time }]</code>, oldest first</td></tr><tr><td><code>GET /api/logs/stream</code></td><td>Loopback only</td><td>Server-Sent Events, one <code>data: {…}</code> per new entry (same shape), after replaying the buffer</td></tr><tr><td><code>GET /api/logs/startup</code></td><td>Loopback only</td><td>The bootstrap log on disk as <code>text/plain</code>, 404 when there is none</td></tr><tr><td><code>GET /api/logs/last-crash</code></td><td>Loopback only</td><td>The last crash dump as <code>text/plain</code>, 404 when there is none</td></tr></tbody></table><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/mcp/config</code></td><td>Token</td><td><code>{ installDir, workspacePath, port, httpUrl }</code> — what the Settings MCP setup guide shows</td></tr><tr><td><code>POST /api/server/restart</code></td><td>Loopback, or Token</td><td>Writes the restart marker and exits so the service manager relaunches the server</td></tr><tr><td><code>/mcp</code></td><td>Token</td><td>The <a href="/guides/ai.html#_2-mcp-server">MCP</a> endpoint (streamable HTTP). Only a caller who may author gets through: 403 <code>OPERATOR_MODE_RESTRICTED</code> for a gated caller, and 403 <code>OPERATOR_SIGN_IN_REQUIRED</code> for an anonymous one under the <code>login</code> visitor policy — send an engineer&#39;s or admin&#39;s account token as <code>X-Muxit-Account</code></td></tr></tbody></table>',34)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
